from typing import Dict

from ta_ue_plugin_android.uepc.ue_manager_exceptions import CannotAttachError
from taf.rfrl.l3_call.pcap.exceptions import AttachMsgsFoundInPcap
from ute_ue.exceptions import DataTransferVerificationFailure

from taf.rfrl.procedures.cloud.setups_teardowns.testing_env import TestingEnv
from taf.rfrl.procedures.resources.python.bts.utils.exceptions import ResultError
from taf.rfrl.procedures.resources.python.bts.utils.pretty_logger import pretty_log
from taf.rfrl.procedures.resources.python.l3_call_cloud import make_l3_call_on_cell_if_requested


def general_siso_auto_cloud_cells_lock_and_unlock(testing_env: TestingEnv,
                                                  throughputs: Dict = None,
                                                  ue_network_modes: Dict[str, str] = None):
    """
    Based on:
    QC Test ID: 304
    QC Test Name: [1.0] Manual_SiSo_SM_NR_cell_lock_unlock_administrative_state_change_from_GUI

    Should report to:
    QC Test ID: 304
    QC Test Name: [1.0] Manual_SiSo_SM_NR_cell_lock_unlock_administrative_state_change_from_GUI

    :param testing_env: testing environment prepared for this test case
    :param throughputs: throughput and deviation values for each Cell identified by its nrCellIdentity for NR Cells,
                        eutranCellId for LTE Cells, wnCelId for WCDMA Cells;
                        i.e.:
                        {'827736065': {'throughput': {'downlink': '100 Mbits/sec',
                                                      'uplink': '15 Mbits/sec},
                                       'deviation': '90%'}}
                        defaults to None (L3 call will not be performed)
    :param ue_network_modes: UE serial numbers paired with desired network modes;
                             i.e. {'HZQN1876AAK90100042': 'NR_only',
                                   'M6AIKN009217SWX': 'LTE_only'}
                             possible UE network modes: 'NR_only', 'LTE_only', 'NR_LTE';
                             when using more than one UE please make sure that modes you choose are either all
                             with '_only' suffix or all are 'NR_LTE' as it is not yet possible to mix those.
                             this param is mandatory for SA+NSA mode;
                             defaults to None (network mode will not be changed on any UE)
    """
    bts = testing_env.btss[0]
    caller = testing_env.caller
    errors = testing_env.errors
    output_dir_path = testing_env.output_dir_path

    _lock_each_cell_and_check_if_it_was_successful(bts, caller, throughputs, ue_network_modes, errors, output_dir_path)
    _check_if_all_cus_are_in_correct_state_when_all_cells_are_locked(bts)
    _unlock_each_cell_and_check_if_it_was_successful(bts, caller, throughputs, ue_network_modes, errors,
                                                     output_dir_path)
    _check_if_all_cus_are_in_correct_state_when_all_cells_are_unlocked(bts)


def teardown_for_general_siso_auto_cloud_cells_lock_and_unlock(testing_env: TestingEnv):
    """
    Teardown for general_siso_auto_cloud_cells_lock_and_unlock test case,
    must be used in [Teardown] of Robot Framework test suite.
    :param testing_env: testing environment prepared for this test case
    """
    bts = testing_env.btss[0]

    for cell in bts.cells:
        if not cell.is_in_state(state='online'):
            try:
                cell.unlock()
                cell.check_state(state='online',
                                 timeout=60)
            except ResultError as exc:
                testing_env.errors.add_from_exception(exc=exc)


@pretty_log
def _lock_each_cell_and_check_if_it_was_successful(bts, caller, throughputs, ue_network_modes, errors, output_dir_path):
    for du in bts.dus:
        if bts.mode == 'NSA':
            du.allow_alarm(fault_id='7300')

        for cell in du.cells:
            try:
                du.cu.allow_alarm(fault_id='7104',
                                  unit_path=cell.config_dist_name)
                cell.lock()
                cell.check_state(state='locked',
                                 timeout=60)
                make_l3_call_on_cell_if_requested(cell=cell,
                                                  caller=caller,
                                                  throughputs=throughputs,
                                                  ue_network_modes=ue_network_modes,
                                                  logs_path=output_dir_path,
                                                  prepare_cells=False,
                                                  expect_attach=False)
            except (ResultError,
                    AttachMsgsFoundInPcap) as exc:
                errors.add_from_exception(exc=exc)

        errors.check()

        if bts.mode == 'NSA':
            du.check_active_alarm(fault_id='7300',
                                  timeout=10)


@pretty_log
def _unlock_each_cell_and_check_if_it_was_successful(bts, caller, throughputs, ue_network_modes, errors,
                                                     output_dir_path):
    for du in bts.dus:
        for cell in du.cells:
            try:
                cell.unlock()
                cell.check_state(state='online',
                                 timeout=60)
                du.cu.disallow_alarm(fault_id='7104',
                                     unit_path=cell.config_dist_name)
                make_l3_call_on_cell_if_requested(cell=cell,
                                                  caller=caller,
                                                  throughputs=throughputs,
                                                  ue_network_modes=ue_network_modes,
                                                  logs_path=output_dir_path,
                                                  prepare_cells=True,
                                                  expect_attach=True)
            except (ResultError,
                    CannotAttachError,
                    DataTransferVerificationFailure) as exc:
                errors.add_from_exception(exc=exc)

        errors.check()

        if bts.mode == 'NSA':
            du.check_inactive_alarm(fault_id='7300',
                                    timeout=10)
            du.disallow_alarm(fault_id='7300')


@pretty_log
def _check_if_all_cus_are_in_correct_state_when_all_cells_are_locked(bts):
    for cu in bts.cus:
        cu.check_state(state='on_air')


@pretty_log
def _check_if_all_cus_are_in_correct_state_when_all_cells_are_unlocked(bts):
    for cu in bts.cus:
        cu.check_state(state='on_air')
